 save(format!("{D}/artifacts/resource-rows.json"),json!(rows.as_array().unwrap().iter().map(|v|{let mut summary=v["summary"].clone();summary.as_object_mut().unwrap().retain(|k,_| !k.starts_with("placement_"));json!({"context":v["context"],"arm":v["arm"],"block":v["block"],"cpu_ms":v["cpu_ms"],"summary":summary})}).collect::<Vec<_>>()));
