 save(format!("{R}/closed.json"),closed.clone());save(format!("{P}/closed.json"),closed.clone());save(format!("{D}/artifacts/closed.json"),closed);save(format!("{D}/artifacts/final-artifacts.json"),json!({"archives":archives,"private_raw_perf_root":format!("{P}/perf"),"no_private_key_image_witness_or_libraries_archived":true}));
 let mut listed=BTreeMap::new();files(&PathBuf::from(format!("{D}/artifacts")),Path::new(D),&mut listed);listed.insert("README.md".into(),hash(format!("{D}/README.md")));fs::write(format!("{D}/SHA256SUMS"),listed.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>()).unwrap();println!("Saved closed screen/profile report, all8 comparisons, resources and hash-checked archive roundtrips; no push.");
